syntax:
extern <type> <array_name> [<size>];
// or
extern <type> <array_name>[];
// Declares an array with external linkage, optionally with size, defined elsewhere.

code_example:
// File: module1.c
int mango[10];  // Definition of the array in one translation unit
// File: module2.c
extern int mango[];  // Declaration of the array in another translation unit
void access_mango() {
    for (int i = 0; i < 10; i++) {
        mango[i] = i * 2;  // Accessing the externally defined array
    }
}
